"""Derive SkyyPets/build_skyypets_0.4.26.py from SkyyPets 0.4.25 (SkyyPets/build_skyypets_0.4.25.py = the SET pin, itself GENERATED by
tools/pets_0_4_25_patch.py - never edit a generated script, edit this patch). Every anchor is asserted once; at the end every change is
undone on a copy and compared with 0.4.25 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/pets_0_4_26_patch.py   then   python SkyyPets/build_skyypets_0.4.26.py   (never --deploy)
      then  python SkyyPets/test_skyypets_0.4.26.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.4.26 (2026-11-17, round inv4) = THE MOUNT CARD'S SUMMON BUTTON (SkyyMenu 0.3.53's inventory screen; Skyy 2026-11-14 docs/answered/pets.md:
  "the mount slot if for riding, i want to summon it with a button or hot key" -> default "a summon button on the HUD mount card"; this round: the button on the
  inventory screen's mount card, riding exactly like today's mount).
  NEW BRIDGE pets:fn:ride (java.util.function.Function, class PetRideFn; published in setup, taken off at stop only while it still holds ours):
  apply(UUID) -> String "+Mounting your <name>" / "=..." (already riding, or the mount is getting ready) / "-<reason>" (no mount out, it is not a ride, the
  ride level, a world without riding, Pets off). It is the SAME door as pressing F on your own summon-slot creature (PetViews.use -> PetRide.request): the
  same canRide rules, the same queued PetRideJob -> PetRide.mountNow on the creature's world (the same world / alive / saddle / already-riding checks), so the
  ride itself is today's. null for anything that is not a UUID. No new system, command, row or item; no saved data.
  NOT this round (queued, RESUME 0a PETS round): summon -> spawns under you and seats you, hop off -> it vanishes (needs the mount-slot rework).
  ROLLBACK: 0.4.26 rolls back alone to 0.4.25 (the key goes away; SkyyMenu 0.3.53 then says the mount button is not available). Earlier Pets floors stand.
'''

P = G.Patch(os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.25.py"), os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.26.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.4.25"') and P.has("PetIdle") and not P.has("PetRideFn"), "not the generated SkyyPets 0.4.25 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("= cls(")

P.rep('''"""SkyyPets 0.4.25 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_25_patch.py from SkyyPets 0.4.24
(build_skyypets_0.4.24.py, the SET pin, itself generated by tools/pets_0_4_24_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.25.py   -> SkyyPets/SkyyPets-0.4.25.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.25.py
''', '''"""SkyyPets 0.4.26 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_26_patch.py from SkyyPets 0.4.25
(build_skyypets_0.4.25.py, the SET pin, itself generated by tools/pets_0_4_25_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.26.py   -> SkyyPets/SkyyPets-0.4.26.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.26.py

''' + NOTE + '''
SkyyPets 0.4.25 (generated by tools/pets_0_4_25_patch.py from 0.4.24) - everything below is still true unless 0.4.26 above says otherwise:
''')
P.rep('VERSION = "0.4.25"\n', 'VERSION = "0.4.26"\n')

# ---- PetRideFn: after PetHudFn's class (every PetRide / PetViews member it calls is already compiled there)
P.rep('''hfn = cls("PetHudFn")
''', '''# 0.4.26 PetRideFn: the bridge pets:fn:ride (SkyyMenu 0.3.53's mount card Summon button) = F on your own summon-slot creature (PetRide.request)
rfn = cls("PetRideFn")
rfn.addInterface(pool.get("java.util.function.Function"))
F(rfn, "public static final java.util.concurrent.atomic.AtomicLong CALLS = new java.util.concurrent.atomic.AtomicLong();")
C(rfn, "public PetRideFn() { }")
M(rfn, r"""
public static String ride(java.util.UUID u, long now) {
  if (!@PKG@.PetsCfg.ON) return "-Pets are switched off on this server";
  @PKG@.PetView v = @PKG@.PetViews.view(u, 2);
  if (v == null || v.gone || v.ref == null) return "-Your mount is not out - put a mount in the mount slot (Pets tab)";
  if (v.riding) return "=You are already riding it";
  String why = @PKG@.PetRide.canRide(v);
  if (why != null && why.length() == 0) return "-Your " + @PKG@.PetRide.petName(v) + " cannot carry you - only mounts and grown dragons can";
  if (why != null) return "-" + why;
  int rq = @PKG@.PetRide.request(u, v, now);
  if (rq == 4) return "+Mounting your " + @PKG@.PetRide.petName(v);
  if (rq == 5) return "=Your " + @PKG@.PetRide.petName(v) + " is already getting ready - one moment";
  return "-Your mount could not take you right now - try again";
}""")
M(rfn, r"""
public Object apply(Object o) {
  CALLS.incrementAndGet();
  if (!(o instanceof java.util.UUID)) return null;
  try { return ride((java.util.UUID) o, @PKG@.PetRide.now()); }
  catch (Throwable t) {
    @PKG@.PetsLog.warnOnce("ridefn:" + t.getClass().getName(), "pets:fn:ride failed (logged once): " + t);
    return "-The ride could not start - try again";
  }
}""")

hfn = cls("PetHudFn")
''')
P.rep('''  @PKG@.PetsLog.bridge().put("pets:fn:hud", new @PKG@.PetHudFn());                   // 0.4.20: the SkyyHud pet widget's lines
''', '''  @PKG@.PetsLog.bridge().put("pets:fn:hud", new @PKG@.PetHudFn());                   // 0.4.20: the SkyyHud pet widget's lines
  @PKG@.PetsLog.bridge().put("pets:fn:ride", new @PKG@.PetRideFn());                 // 0.4.26: the inventory mount card's Summon button
''')
P.rep('''    if (hf instanceof @PKG@.PetHudFn) br.remove("pets:fn:hud", hf);
''', '''    if (hf instanceof @PKG@.PetHudFn) br.remove("pets:fn:hud", hf);
    Object rf = br.get("pets:fn:ride");          // 0.4.26: only ours
    if (rf instanceof @PKG@.PetRideFn) br.remove("pets:fn:ride", rf);
''')
P.rep('''; 0.4.20: pets:fn:hud (the SkyyHud pet widget); kit @KITID@''', '''; 0.4.20: pets:fn:hud (the SkyyHud pet widget); 0.4.26: pets:fn:ride (the inventory mount card); kit @KITID@''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("= cls(") == CLS0 + 1, "0.4.26 adds PetRideFn, no system, no command"
P.finish()
